import java.io.*;
import java.util.*;

public class Main {
    static class Node {
        long key;
        int priority;
        int count;
        int size;
        Node left, right;

        Node(long key, int priority) {
            this.key = key;
            this.priority = priority;
            this.count = 1;
            this.size = 1;
        }
    }

    static Random rnd = new Random();

    static int size(Node n) {
        return n == null ? 0 : n.size;
    }

    static void update(Node n) {
        if (n != null) {
            n.size = n.count + size(n.left) + size(n.right);
        }
    }

    static Node rotateRight(Node y) {
        Node x = y.left;
        y.left = x.right;
        x.right = y;
        update(y);
        update(x);
        return x;
    }

    static Node rotateLeft(Node x) {
        Node y = x.right;
        x.right = y.left;
        y.left = x;
        update(x);
        update(y);
        return y;
    }

    static Node insert(Node node, long key) {
        if (node == null) {
            return new Node(key, rnd.nextInt());
        }

        if (key == node.key) {
            node.count++;
            update(node);
            return node;
        }

        if (key < node.key) {
            node.left = insert(node.left, key);
            if (node.left.priority < node.priority) {
                node = rotateRight(node);
            }
        } else {
            node.right = insert(node.right, key);
            if (node.right.priority < node.priority) {
                node = rotateLeft(node);
            }
        }

        update(node);
        return node;
    }

    static int countLessEqual(Node node, long key) {
        int result = 0;

        while (node != null) {
            if (key < node.key) {
                node = node.left;
            } else if (key > node.key) {
                result += size(node.left) + node.count;
                node = node.right;
            } else {
                result += size(node.left) + node.count;
                break;
            }
        }

        return result;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        StringBuilder sb = new StringBuilder();
        Node root = null;
        int previousPenalty = 0;

        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            long x = Long.parseLong(st.nextToken());
            long y = Long.parseLong(st.nextToken());

            x += previousPenalty;
            y += previousPenalty;

            long dist = x * x + y * y;
            int penalty = countLessEqual(root, dist);

            sb.append(penalty).append('\n');

            root = insert(root, dist);
            previousPenalty = penalty;
        }

        System.out.print(sb);
    }
}
